    },
    [2081367] = {
        id = 2081367,
        text = "บ๊ะจ่างที่ทำในห้องเรียนวิชาทำอาหารที่โรงเรียน ธัญพืชต่างๆ ล้วนถูกคัดสรรมา โทวกะและโอริกามิทำมันมาให้คุณ",
        minipack = 0,
    },
    [2081368] = {
