    [2081377] = {
        id = 2081377,
        text = "ตำนานเล่าว่าในเทศกาลเรือมังกรจะมีปีศาจปรากฎตัวออกมาและข้าวเหนียวสามารถกำจัดพวกมันได้ และมันเป็นวัตถุดิบที่จำเป็นในการทำบ๊ะจ่าง",
        minipack = 0,
    },
    [2081378] = {
        id = 2081378,
        text = "ข้าวโพดหวานและสดใหม่ที่อวบอิ่ม มันจะทำให้บ๊ะจ่างอร่อยขึ้น",
