        minipack = 0,
    },
    [63027] = {
        id = 63027,
        text = "ทำงานเป็นวิธีที่ดีที่รับรางวัล!\n\nต้องทำงานให้เสร็จถึงจะได้รับรางวัล ร้านค้าที่แตกต่างกันจะให้รางวัลที่แตกต่างกัน การทำงานจะได้รับ EXP สำหรับงานนั้น รับ EXP เพียงพอที่จะเพิ่มระดับงาน ซึ่งจะนำไปสู่รางวัลที่ดีขึ้น~",
        minipack = 0,
    },
    [910098] = {
        id = 910098,
        text = "ในเทพนิยายไม่มีเรื่องจริง แต่พวกมันก็สามารถกระตุ้นหัวใจของทุกคนได้",
        minipack = 0,
    },
    [910099] = {
        id = 910099,
        text = "ดูเหมือนว่ากำลังมีงานฉลองเทศกาลใหญ่ในศาลเจ้า จะมีการแสดงหรือเปล่า...",
        minipack = 0,
    },
    [910100] = {
        id = 910100,
        text = "นี่มันไม่น่าเชื่อเลย! ร้านอาหารริมทางมีงานเลี้ยงฟรี!",
        minipack = 0,
    },
    [910101] = {
        id = 910101,
        text = "เมื่อชิงช้าสวรรค์ไปถึงจุดสูงสุด ความปรารถนาของคุณจะเป็นจริง",
