    [63057] = {
        id = 63057,
        text = "เลี้ยง? หลอก! ——\n\nกิจกรรมฮาโลวีนเริ่มแล้ว! ห้ามพลาดกับของรางวัลมากมาย!\n\n1. ผู้เล่นสามารถเข้าร่วมกิจกรรม [สำรวจปราสาท] เพื่อสำรวจห้องต่าง ๆ ต่อสู้กับศัตรู และรับรางวัล\n\n2. เหรียญกษัตริย์ฟักทองที่ได้รับจากกิจกรรมสำรวจปราสาท สามารถใช้แลกเป็นของขวัญได้ที่ร้านแลกเปลี่ยน",
        minipack = 0,
    },
    [2200480] = {
        id = 2200480,
        text = "กระโดดขึ้นไปเพื่อโจมตีกลับศัตรูที่อยู่ใกล้เคียง และยิงศัตรูต่อเนื่องจากด้านบน\nสร้าง DMG พลังมืดเท่ากับ 90% ATK 4 ครั้ง",
        minipack = 0,
    },
    [14110015] = {
        id = 14110015,
        text = "รูนจารึกเปิดความท้าทายทีมระดับ D แบบสุ่ม เหมาะสำหรับผู้เล่น Lv.30",
        minipack = 0,
