    [14110119] = {
        id = 14110119,
        text = "",
        minipack = 0,
    },
    [2200510] = {
        id = 2200510,
        text = "รูปแบบง้าว: \nการโจมตีกลุ่มด้วยภูติเผาทำลาย: ง้าว โจมตี 3 ครั้งอย่างต่อเนื่อง\nช่วงที่1: สร้าง DMG กายภาพ 1 ครั้ง จาก 70% ของ ATK\nช่วงที่ 2: สร้าง DMG กายภาพ 1 ครั้ง จาก 80% ของ ATK\nช่วงที่ 3: สร้าง DMG กายภาพ 1 ครั้ง จาก 90% ของ ATK\nรูปแบบปืนใหญ่:\nโจมตีศัตรูด้านหน้าด้วยภูติเผาทำลาย: ปืนใหญ่ ทำการโจมตี 3 ครั้งอย่างต่อเนื่อง\nการโจมตีแต่ละครั้งจะสร้าง DMG เปลวไฟเท่ากับ 100% ATK 1 ครั้ง มีโอกาส 30% ที่จะทำให้เป้าหมายจุดไฟ",
        minipack = 0,
    },
    [2200512] = {
        id = 2200512,
        text = "การพิพากษาจากนรก",
        minipack = 0,
    },
    [14110143] = {
        id = 14110143,
        text = "Lv.70",
        minipack = 0,
    },
    [14110151] = {
        id = 14110151,
        text = "กุญแจหินชาร์ม",
        minipack = 0,
    },
    [14110159] = {
        id = 14110159,
        text = "โอกาสรับรางวัลรายวันจากความท้าทายรูนจารึกระดับ A",
        minipack = 0,
    },
    [2200520] = {
        id = 2200520,
        text = "รูปแบบง้าว: \nโจมตีศัตรูที่อยู่ใกล้ ๆ และโจมตีอย่างต่อเนื่อง\nสร้างDMG กายภาพ3 ครั้งจาก 280% ของ ATK มีโอกาส 100% ที่จะทำให้เป้าหมายจุดไฟ\nรูปแบบปืนใหญ่:\nกระโดดขึ้นและปล่อยลูกบอลไฟขนาดยักษ์ไปข้างหน้า\nระเบิดลูกบอลไฟเพื่อสร้างDMG เปลวไฟ 1ครั้งจาก 390%ของ ATK ต่อศัตรูที่อยู่ติดกัน มีโอกาส100%ที่จะทำให้เป้าหมายจุดไฟ",
        minipack = 0,
    },
    [2200522] = {
        id = 2200522,
        text = "รูปแบบง้าว: \nกระโดดเข้าหาและตีหนัก 1 ครั้ง\nสร้าง DMG เปลวไฟ 1 ครั้งจาก 150% ของATK\nรูปแบบปืนใหญ่: \nยิงลูกบอลไฟ 1ลูกหลังจากเติมพลัง ลูกบอลจะกลายเป็นหลุมดำเพื่อดึงเร้าศัตรูที่อยู่ใกล้ๆเข้าไป\nลูกบอลไฟจะสร้าง DMG เปลวไฟเท่ากับ 30%ของ ATK ให้กับศัตรูตัวแรกที่สัมผัสมัน หลุมดำจะสร้าง DMG เปลวไฟ 7 ครั้งจาก 170% ของพลังโจมตี ต่อเนื่อง 4 วินาที",
        minipack = 0,
    },
    [14110183] = {
        id = 14110183,
        text = "เอาชนะ Boss: โทคิซากิ คุรุมิ",
        minipack = 0,
    },
    [14110191] = {
