    [14110199] = {
        id = 14110199,
        text = "สำรวจ [ประตูชาร์ม] ในบริเวณนี้ ค้นหา และเอาชนะ Boss ของพื้นที่",
        minipack = 0,
    },
    [2200530] = {
        id = 2200530,
        text = "ถล่มศัตรูที่อยู่ด้านหน้าด้วยลำแสงเปลวเพลิงของภูติเผาทำลาย: ปืนใหญ่\nสร้าง DMG เปลวไฟเท่ากับ 625% ATK ในการโจมตี 25 ครั้ง\nภูติเผาทำลาย: รูปแบบปืนใหญ่ต้นทุน 4 ความโกรธทุกวินาที เมื่อความโกรธลดลงเหลือ 0 ให้เปลี่ยนกลับเป็นรูปแบบขวานโบราณ",
        minipack = 0,
    },
    [14110215] = {
        id = 14110215,
        text = "Lv.70",
        minipack = 0,
    },
    [14110223] = {
        id = 14110223,
        text = "[ประตูชาร์ม] ที่ปรากฏนั้นได้เชื่อมต่อโลกแห่งความจริงกับอีกโลกหนึ่งเอาไว้ ผู้เล่นทุกคนจำเป็นต้องเคลื่อนไหวภายใต้การนำของหัวหน้า จากนั้นค้นหาตำแหน่งของห้องสุดท้าย และเอาชนะ Boss ของพื้นที่",
        minipack = 0,
