        minipack = 0,
    },
    [1701448] = {
        id = 1701448,
        text = "อร๊า ของขวัญนี้จะมอบให้ใครหรอ... อะไรนะ? ฉันหรอ!? คุณกำลังพูดถึงอะไร... ขอบคุณนะ",
