    },
    [1701450] = {
        id = 1701450,
        text = "มูลค่าของมันสูงสุดแล้ว...",
        minipack = 0,
    },
    [1701451] = {
        id = 1701451,
        text = "อะไรนะ? น้องสาวที่น่ารักแบบนั้น แยกกันหน่อยก็รู้สึกไม่ดีแล้วหรอ",
        minipack = 0,
    },
    [1701452] = {
        id = 1701452,
        text = "ชุดสปิริตหรือข้อมูลพวกนั้น ไม่สามารถเอามาประเมินความสามารถของฉันได้",
