    },
    [1701454] = {
        id = 1701454,
        text = "ตอนนี้ มาเริ่มการเดท (ต่อสู้) ของเรากัน",
        minipack = 0,
    },
    [1701455] = {
        id = 1701455,
        text = "ฉันจะแข็งแกร่งขึ้นอีก สำหรับทุกคน สำหรับคุณ.. ไม่ ไม่มีอะไร",
