    },
    [1701549] = {
        id = 1701549,
        text = "นี้คืออะไร ถ้างั้นคุณอยากจะให้ฉันดีใจ งั้นก็ช่วยฉันทำวิจัยล่ะกัน",
        minipack = 0,
    },
    [1701550] = {
        id = 1701550,
        text = "ดี ดี... การได้รับคำชมจากคนแบบคุณ ไม่ได้ทำให้ฉันมีความสุขเลย",
        minipack = 0,
    },
    [1701551] = {
        id = 1701551,
        text = "ฉันเป็นพ่อมดที่แข็งแกร่งที่สุด",
