        text = "มันคืออะไรกัน โอ้? ของขวัญให้ฉันหรอ",
        minipack = 0,
    },
    [1702002] = {
        id = 1702002,
        text = "ถ้าหากคุณอยากจะหยุด ก็ทำเถอะ มันจะดีกว่าถ้าจะมอบให้กับผู้หญิงคนอื่น",
        minipack = 0,
    },
    [1702003] = {
