    [1702053] = {
        id = 1702053,
        text = "[เควสหลัก] นัตสึมิ_บทที่ 1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "สาวน้อยผู้มีผมสีดำเหมือนหมึก มีดวงตาสุกสกาวเหมือนดวงดาว",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "ถึงแม้จะมีสถานะเป็นนักรบที่แข็งแกร่ง แต่ก็ไม่สามารถปกปิดหัวใจสาวน้อยของเธอได้",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "ด้วยหัวใจที่เปราะบางเหมือนแก้ว เธอกลัวคนแปลกหน้าและต้องการคนดูแล",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "พลังที่แข็งแกร่งและน่าเกรงขาม ทำให้เธอยิ่งดูสวยบาดใจ",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "เธอมักจะดูสงบนิ่งตลอดเวลา แต่ว่าเธอมักจะตกอยู่ในหลุมของความอบอุ่นจากพี่ชาย",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "[ความรัก] คือเหตุผลเดียวที่เธอมีตัวตนอยู่ เธอยืนอยู่บนจุดสูงสุดดุจดั่งเทวทูต",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "เธอจะแสดงตัวตัวต่อหน้าบุคคลที่เชื่อมั่นเท่านั้น",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "วันวาเลานไทน์หรอ อืม... สำหรับฉันแล้ว ถ้าฉันได้ออกเดทกับคุณ มันก็เป็นวันที่ดีทั้งนั้น \nตอนที่อยู่กับฉัน คุณเองก็มีความสุขใช่ไหม",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "ถึงสุดที่รัก หวังว่าคุณจะยอมรับดอกไม้และจดหมายรักของฉัน\n มาสิ มาใช้เวลาในช่วงกลางคืนด้วยกันกับฉัน",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "โยชิโนะแข็งแกร่งกว่าเมื่อก่อน...\n สะ- สุขสันต์วันวาเลนไทน์~",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "อร๊า ถึงแม้จะเป็นการพบกันเพราะโชคชะตา บางครั้งฉันก็ยังรู้สึกว่าโชคดีมาก\n ที่ได้รอคอยที่จะได้พบกับคุณ",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "ไอ้เจ้าพี่บ้า เทศกาลนี้มันสำหรับคู่รัก แต่ว่าฉันก็มีเรื่องอยากจะบอกคุณ\n ขอบคุณที่อยู่ตรงนี้เสมอ",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "วันนี้ฉันจะเดินจับมือคุณเดินไปในเส้นทางที่เต็มไปด้วยดอกไม้ หรือว่าใต้ต้นไม้ที่มีใบไม้ร่วงโปรยปราย\n จนกว่าแสงจากดวงอาทิตย์จะทำให้เงาของพวกเรายาวออกไป",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "ที่จริงแล้ว ฉันก็อยากจะซื่อสัตย์กับคุณบ้างนะ...\nแต่ว่าฉันกำลังรอคอยเวลาที่เหมาะสมอยู่",
        minipack = 0,
    },
    [1702068] = {
        id = 1702068,
        text = "[กิจกรรม] สงครามช็อกโกแลต",
        minipack = 0,
    },
