    },
    [1702123] = {
        id = 1702123,
        text = "หึ หึ หึ ไม่มีทางที่จะหลอกฉันได้หลอก นอกจากคำพูดของฉันเอง ฉันไม่เชื่ออะไรทั้งนั้น",
        minipack = 0,
    },
    [1702124] = {
        id = 1702124,
        text = "เป็นความจริงหรอ... ถึงแม้ว่าเสียงของฉันจะหายไป คุณจะยังคงเป็นแฟนคลับของฉันไหม",
        minipack = 0,
    },
    [1702125] = {
        id = 1702125,
        text = "อะไรนะ? จู่ๆ ก็อยากจะได้ยินฉันร้องเพลงหรอ คิคิ ได้ทุกเวลา~",
