    [1702416] = {
        id = 1702416,
        text = "ในระหว่างที่สร้างอพาร์ทเม้นแห่งนี้ โคโทริอยากจะให้สปิริตได้อาศัยอยู่ในโลกสีชมพู ถึงจะเป็นคุรุมิที่แสนทะนงตน ก็มีด้านที่เป็นสาวน้อยเช่นกัน (ถึงแม้ว่าเธอจะไม่ได้อาศัยอยู่ที่นี่ด้วย^0^)",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "เพื่อที่จะเรียนรู้เรื่องในชีวิตประจำวันของสปิริต ลองไปเยี่ยมชมห้องนั่งเล่นบ่อยๆ สิ คุณอาจจะได้รับ \"บริการ\" พิเศษบางอย่าง",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "ที่นี่คือสถานที่สปิริตจะนอนในตอนกลางคืน อยากจะให้ห้องมองเห็นวิวของเมืองเทนกุในตอนกลางคืน น่าจะช่วยทำให้นอนหลับฝันหวาน",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "ทุกคืนในห้องนั่งเล่นที่เหล่าสปิริตอาศัยอยู่ ถ้าหากทีวีเปิดอยู่ คุณจะได้ยินเสียงร้องไห้ของโยชินอน และเสียงกรีดร้องของนัตสึมิแน่นอน นั่นหมายความว่าละครกำลังเล่นอยู่",
        minipack = 0,
    },
    [1702420] = {
