        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "แม้แต้แสงอาทิตย์ที่ส่องสว่างที่สุดก็ยังไม่สามารถส่องไปถึงยังหัวใจของสปิริต ทำไมสปิริตจะต้องมานั่งและรับฟังคุณครูด้วยนะ น่าปวดหัวจริงๆ",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "นักเรียนขี้เกียจบางครั้งก็มักจะไปรวมตัวกันในห้องเรียนที่ว่างเปล่า มีคนเล่าว่าเคยเห็นนักเรียนหญิงลึกลับในชุดสีแดงหน้าตาน่ารักทีเดียว",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "ระเบียงที่ทำให้นักเรียนนึกถึงตอนที่ถูกทำโทษให้มายืนอยู่ตรงนี้ มันจะครึกครื้นทุกครั้งที่เลิกเรียน ช่างเป็นช่วงเวลาที่ดีเหลือเกิน",
