        minipack = 0,
    },
    [1702490] = {
        id = 1702490,
        text = "ผู้คนที่อาศัยอยู่ที่นี่ล้วนเป็นมิตร พวกเขายิ้มให้คุณเมื่อเดินผ่านไป",
        minipack = 0,
    },
    [1702491] = {
