        text = "สิ่งที่น่าดึงดูที่สุดด้านนอกนั้นคือตัวเมือง เหมาะที่จะมาเยี่ยมชมในทุกฤดูกาล",
        minipack = 0,
    },
    [1702492] = {
        id = 1702492,
        text = "This is a famous scene. A banner hung near the handrail said, \"Do not lean against or climb.\" Yep, we have to be safe.",
        minipack = 0,
    },
    [1702493] = {
