    },
    [1702494] = {
        id = 1702494,
        text = "",
        minipack = 0,
    },
    [1702495] = {
        id = 1702495,
        text = "ถ้าหากคุณเห็นใครกำลังเล่นมือถือในขณะที่เดินอยู่ ในทำให้พวกเขาตกใจซะ ล้อเล่นนะ อย่าไปชนใครเข้าล่ะ",
        minipack = 0,
    },
    [1702496] = {
