        text = "มีทัศนคติที่ดีต่อมนุษย์ แต่อาจหงุดหงิดถ้าพูดไม่เข้าหู (อาจทำให้เกิดการต่อสู้)",
        minipack = 0,
    },
    [11003008] = {
        id = 11003008,
        text = "[กาเบรียล] สร้าง DMG ให้ศัตรู +20%",
        minipack = 0,
    },
    [11003016] = {
        id = 11003016,
        text = "[กาเบรียล] ในการโจมตีจะมีโอกาส 20% ที่จะได้รับ +20% DEF เป็นเวลา 6 วินาที",
        minipack = 0,
    },
    [11003024] = {
        id = 11003024,
        text = "[กาเบรียล] ระยะ ATK +20%",
        minipack = 0,
    },
    [11003032] = {
        id = 11003032,
        text = "[มีนาคม] ริทึ่มโซนิคระเบิดภายในพื้นที่เล็ก ๆ\nสร้าง DMG วิญญาณเท่ากับ 180% ATK",
        minipack = 0,
    },
    [11003040] = {
        id = 11003040,
        text = "[มีนาคม] เมื่อริทึ่มโซนิคระเบิด จะดึงเร้าศัตรูทั้งหมดมาที่ศูนย์กลาง\nสร้าง DMG วิญญาณ เท่ากับ 200% ATK",
        minipack = 0,
    },
    [11003048] = {
        id = 11003048,
        text = "[มีนาคม] จะลด ATK ของเป้าหมาย -25% เมื่อโจมตีโดน",
        minipack = 0,
    },
    [11003056] = {
        id = 11003056,
        text = "การใช้ [คอนเสิร์ท] จะเพิ่ม DEF/ต้าน Crit ขึ้น 40%/12% ตามลำดับ ต่อเนื่อง 5 วินาที",
        minipack = 0,
    },
    [11003064] = {
        id = 11003064,
        text = "[คอนเสิร์ท] สกิลความเร็ว ATK +20%",
        minipack = 0,
    },
    [11003072] = {
        id = 11003072,
        text = "[คอนเสิร์ท] ในการโจมตีจะมีโอกาส 20% ที่จะล่อดึงดูดเป้าหมาย\n[ดึงดูดไป 10 วินาที ล่อลวงเป้าหมายเป็นเวลา 8 วินาที ซ้อนกัน 3 ครั้ง ล่อลวงเป้าหมาย จะช่วยมิคุโจมตีผู้อื่น Boss มีคุ้มกันล่อลวง]",
        minipack = 0,
    },
    [11003080] = {
        id = 11003080,
        text = "หลังจากใช้ [คอนเสิร์ท] จะทิ้งวงกลมแสงไว้บนพื้นเพื่อสร้างดาเมจแก่ศัตรูที่อยู่ใกล้ ๆ เป็นระยะ ๆ\nสร้างดาเมจได้สูงสุด 10 ครั้ง สร้าง DMG วิญญาณเท่ากับ 25% ของ ATK ของ มิคุ",
        minipack = 0,
    },
    [11003088] = {
        id = 11003088,
        text = "[บรรเลง] ดนตรีดึงเร้าศัตรูที่อยู่ใกล้ ๆ เข้ามา",
        minipack = 0,
    },
    [11003096] = {
        id = 11003096,
        text = "[บรรเลง] วงกลมแสงจะลดโน้ตดนตรีลงทั้งหมด 7 โน้ต\nลูกบอลโน้ตดนตรีแต่ละลูกจะสร้าง DMG วิญญาณเท่ากับ 21% ATK 1 ครั้งต่อการโจมตี",
        minipack = 0,
    },
    [11003104] = {
        id = 11003104,
        text = "เมื่อเป้าหมายเสียชีวิตขณะติดสถานะล่อลวง มันจะสำรวจ 1 ครั้งเมื่อเสียชีวิต",
        minipack = 0,
    },
    [11003112] = {
        id = 11003112,
        text = "ถ้าโจมตีได้เป้าหมาย จะทำให้สปีดเคลื่อนไหวของเป้าหมาย -6% เป็นเวลา 3 วินาที ซ้อนกันได้สูงสุด 5 ชั้น",
