    [13310525] = {
        id = 13310525,
        text = "เรียน ผู้ทำสัญญา \n เราต้องขออภัยเป็นอย่างยิ่งที่ไม่ได้ทำการชี้แจงเกี่ยวกับกลไกป้องกันที่คงความสมดุลระหว่างผู้เล่นผู้โชคดีและโชคร้ายให้ชัดเจนในกติกาการร่วมกิจกรรม ทำให้เกิดการเข้าใจผิดในกลุ่มผู้เล่นด้วยกัน ขออภัยกับความสับสนที่เกิดขึ้น \n แม้จะมีความตั้งใจที่จะเพิ่มรูปแบบที่เป็นมิตรแก่ผู้ใช้งาน แต่เนื่องจากขาดการพิจารณาที่รอบคอบ คำอธิบายที่ชัดเจน ตลอดจนการนำไปใช้งาน ทำให้ได้ผลลัพธ์ก็ไม่เป็นไปตามที่เราคาดหวัง ในฐานะที่ยังเป็นสตูดิโอน้องใหม่ เราจะพยายามเรียนรู้และปรับปรุงให้ดีขึ้น ขอขอบคุณที่เข้าใจและให้การสนับสนุน!\n- Hot Games",
        minipack = 0,
    },
    [213109] = {
        id = 213109,
