    [10503024] = {
        id = 10503024,
        text = "รูปแบบขวานโบราณ: \n[ภูติเผาทำลาย รูปแบบขวานโบราณ] ระยะ ATK +20%\nรูปแบบปืนใหญ่:\n[ภูติเผาทำลาย: ปืนใหญ่] เมื่อโจมตี ขยายระยะขึ้น 20% สำหรับทริกเกอร์การสำรวจ",
        minipack = 0,
    },
    [10503032] = {
        id = 10503032,
        text = "[การแก้แค้นที่ลุกเป็นไฟ] สกิล DMG +20%",
        minipack = 0,
    },
    [10503040] = {
        id = 10503040,
        text = "[การแก้แค้นที่ลุกเป็นไฟ] สกิลอัตราทะลวง +7%",
        minipack = 0,
    },
    [1706139] = {
        id = 1706139,
        text = "มีสาวต้อนรับ - ฮิโกะโรโมะ ฮิบิกิ",
        minipack = 0,
    },
    [10503056] = {
        id = 10503056,
        text = "รูปแบบขวานโบราณ:\nโจมตีหนักเสกเปลวไฟจากน้อยไปหามาก\nเปลวไฟสร้าง DMG เปลวไฟเท่ากับ 30% ATK 6 ครั้ง\nรูปแบบปืนใหญ่:\nเพิ่มแรงดึงเร้าของลูกบอลไฟสีดำ",
        minipack = 0,
    },
    [10503064] = {
        id = 10503064,
        text = "รูปแบบขวานโบราณ:\nในแต่ละครั้ง เปลวไฟสร้างความเสียหายเท่ากับ 50% ของ ATK เปลวไฟยังคงอยู่บนพื้นเป็นเวลา 3 วินาที\nเปลวไฟบนพื้นสร้าง DMG เปลวไฟเท่ากับ 180% ATK ใน 4 ครั้ง\nแบบฟอร์มปืนใหญ่:\nสกิลสามารถร่ายได้โดยตรงโดยไม่ต้องเติมพลัง",
        minipack = 0,
    },
    [10503072] = {
        id = 10503072,
        text = "รูปแบบขวานโบราณ:\nในแต่ละครั้ง เปลวไฟสร้างความเสียหายเท่ากับ 60% ของ ATK ระยะของเปลวไฟบนพื้น +20%\nรูปแบบปืนใหญ่:\nเมื่อลูกบอลเพลิงสีดำสำรวจ สร้างดาเมจอีก 1 ครั้ง สร้าง DMG เปลวไฟเท่ากับ 70% ATK",
        minipack = 0,
    },
    [1706143] = {
        id = 1706143,
        text = "มีสาวต้อนรับ - ควีน",
        minipack = 0,
    },
    [10503088] = {
        id = 10503088,
        text = "รูปแบบง้าว: \nเสาเปลวเพลิงที่เกิดจากการกระโดดสังหารครั้งล่าสุดจะใหญ่ขึ้น สกิลนี้สร้าง DMG กายภาพ เท่ากับ 770% ของ ATK ของโคโทริ\nรูปแบบปืนใหญ่:\nบริเวณการระเบิด + 20% บริเวณการโจมตีของเปลวไฟบนพื้น + 20% ดาเมจของสกิลเพิ่มขึ้น สกิลทั้งหมดสามารถสร้าง DMG เปลวไฟได้ 460% ของATK โคโทริ",
        minipack = 0,
    },
    [10503096] = {
        id = 10503096,
        text = "[เปลวไฟตัดสิน] สกิล DMG +20%",
        minipack = 0,
    },
    [10503104] = {
        id = 10503104,
        text = "ในรูปแบบขวานโบราณ โอกาสที่จะทำให้เป้าหมายจุดไฟในขณะโจมตี +20% และDMGสกิล ของโคโทริ +50% \n[เป้าหมายที่ถูกจุดไฟจะได้รับ DMG เท่ากับ 10% ของ ATK ของโคโทริในทุกๆวินาที ต่อเนื่อง 8 วินาที ซ้อนกันได้สูงสุด 10 ชั้น หลังจากถึงชั้นสูงสุด โคโทริจะจุดระเบิดเปลวไฟแก่เป้าหมายเพิ่มเติม 1 ครั้ง สร้าง DMG เท่ากับ 30% ของ ATK ของโคโทริในบริเวณเล็ก ๆ ดาเมจจากการระเบิดจะคำนวณค่า DEF ของเป้าหมายใหม่อีกครั้ง]",
        minipack = 0,
    },
