        minipack = 0,
    },
    [2108208] = {
        id = 2108208,
        text = "3. หากคุณใช้งานตัวละครมีที่เนื้อเรื่อง [คริมสัน ไนท์แมร์] ในอาณาจักรคริมสัน คุณสมบัติของเธอจะเพิ่มขึ้น แต่ว่าสำหรับตัวละครทดสอบในด่านนี้เท่านั้น ไม่ใช่สำหรับัวละครจริงของคุณ",
        minipack = 0,
    },
    [2108210] = {
        id = 2108210,
        text = "5. ตัวละครทดสอบ [คริมสัน ไนท์แมร์] ใน [อาณาจักรคริมสัน] สามารถใช้งานได้ในด่านหลัก, ด่านโรงละคร, ด่านคอลาโบ (ระดับยากสำหรับ 2 โหมดนี้), ด่านประจำวัน และทดสอบสปิริต เมื่อสิ้นสุดกิจกรรม เธอจะถูกลบทิ้ง",
