    [10951242] = {
        id = 10951242,
        text = "หากไม่ดาเมจใน 5 วินาที, จะได้รับ ความเร็ว ATK +20% และ สปีดเคลื่อนไหว +20%, หากได้รับดาเมจจะล้างเอฟเฟกต์ไป",
        minipack = 0,
    },
    [1020352] = {
        id = 1020352,
        text = "อย่าบอกว่าฉันไม่ได้ช่วยคุณ ~",
        minipack = 0,
    },
    [13310526] = {
        id = 13310526,
        text = "เรียนผู้ทำสัญญา\nขอบคุณสำหรับการสนับสนุนของทุกคน อนิเมะ Date A Live ซีซัน 3 ได้เริ่มขึ้นแล้ว! ภรรยาของเรากำลังเคลื่อนไหวมาที่ทางของเรา!\nเราพยายามเพื่อโปรโมต DAL เราหวังว่าคุณจะสนับสนุนพวกเราต่อไป!\nการเดทที่ไม่มีสิ้นสุด!\n-Hot Games",
        minipack = 0,
    },
    [1020353] = {
        id = 1020353,
        text = "ฉันจะไม่ยอมแพ้ง่ายๆ!",
        minipack = 0,
    },
    [13310542] = {
        id = 13310542,
        text = "เรียนพันธสัญญาที่รัก\nราทาโทสพบว่าค่าอารมณ์ของโทบิอิจิ โอริกามิ กำลังลดดิ่งลงโดยไม่ทราบสาเหตุ และขณะนี้สถานการณ์ในที่เกิดเหตุนั้นกำลังเข้าสู่ขั้นวิกฤต สถานการณ์ฉุกเฉิน! โปรดเตรียมพร้อมออกไปสำรวจ และอย่าลืมใส่ใจปกป้องความปลอดภัยของคุณ\nHot Games ทำงานอย่างหนักเพื่อที่จะทำให้โอริกามิออกมาดูดี",
        minipack = 0,
    },
    [13310550] = {
        id = 13310550,
        text = "ตามคำสั่งผู้บัญชาการโคโทริ ตอนนี้ฉันพยายามติดต่อกับสปิริตที่ทำให้เกิดการสั่นสะเทือนในอวกาศ",
        minipack = 0,
    },
    [13310558] = {
        id = 13310558,
        text = "ริบบิ้น ลูกโป่ง และเค้ก... ขอบคุณสำหรับมิตรภาพดี ๆ สุขสันต์วันครบรอบปีแรก!",
        minipack = 0,
    },
    [13310566] = {
        id = 13310566,
        text = "สวัสดีปีใหม่! โปรดรับคำอวยพรจากสปิริต",
        minipack = 0,
    },
    [13310574] = {
        id = 13310574,
        text = "ในวันที่ปาฏิหาริย์ได้เกิดขึ้น กลิ่นหอมหวานที่ดึงดูดใจก็ได้พุ่งเข้ามาในจมูกของฉัน",
        minipack = 0,
    },
    [13310582] = {
