    },
    [10503009] = {
        id = 10503009,
        text = "รูปแบบขวานโบราณ: \n[ภูติเผาทำลาย ขวานโบราณ] โจมตีศัตรูต่อเนื่อง 4 ครั้ง\n 4 โจมตี: สร้าง DMG กายภาพ 1 ครั้ง จาก 100% ของ ATK\nรูปแบบปืนใหญ่:\n[ภูติเผาทำลาย: ปืนใหญ่] เมื่อโจมตี ยิงลูกไฟที่ระเบิด 1 ครั้ง\nสร้าง DMG เปลวไฟเท่ากับ 100% ATK 1 ครั้ง",
        minipack = 0,
    },
    [10503017] = {
        id = 10503017,
        text = "[ภูติเผาทำลาย] สร้าง DMG ให้ศัตรูที่เป็นมนุษย์ +2%",
        minipack = 0,
    },
    [10503025] = {
        id = 10503025,
        text = "[ภูติเผาทำลาย] มีโอกาส 4% ที่จะทำให้เป้าหมายจุดไฟในขณะโจมตี\n[เป้าหมายที่ถูกจุดไฟจะได้รับ DMG เท่ากับ 10% ของ ATK ของโคโทริในทุกๆวินาที ต่อเนื่อง 8 วินาที ซ้อนกันได้สูงสุด 10 ชั้น หลังจากถึงชั้นสูงสุด โคโทริจะจุดระเบิดเปลวไฟแก่เป้าหมายเพิ่มเติม 1 ครั้ง สร้าง DMG เท่ากับ 30% ของ ATK ของโคโทริในบริเวณเล็ก ๆ ดาเมจจากการระเบิดจะคำนวณค่า DEF ของเป้าหมายใหม่อีกครั้ง]",
        minipack = 0,
    },
    [10503033] = {
        id = 10503033,
        text = "รูปแบบขวานโบราณ:\nหลังจากยกศัตรูขึ้นบินหนีแล้ว ให้ทำการโจมตีแนวนอน 2 ครั้งด้วยขวานโบราณ สกิลนี้สร้าง DMG กายภาพ เท่ากับ 660% ของ ATK ของโคโทริ\nรูปแบบปืนใหญ่:\n ลำแสงไฟอยู่ได้นานขึ้นสร้าง DMG เปลวไฟ เท่ากับ 450% ของ ATK ของโคโทริ",
        minipack = 0,
    },
    [10503041] = {
