    [2130510] = {
        id = 2130510,
        text = "เคยทำการดัดแปลงแล้ว",
        minipack = 0,
    },
    [266326] = {
        id = 266326,
        text = "ผ่านด่านทดสอบสปิริต 6 ครั้ง",
        minipack = 0,
    },
    [2130514] = {
        id = 2130514,
        text = "1. ความขัดแย้งคริสต์มาส: \nทำภารกิจให้สำเร็จเพื่อสปิริต แล้วคุณจะได้รับของขวัญคริสต์มาสจากพวกเขา! คุณจะได้รับสโนว์บอล, เซฟิร่าคริสต์มาส 2020, CG คริสต์มาสพิเศษ 2020!\n\n2. ความขัดแย้งมนุษย์หิมะ: \nคริสต์มาสกำลังจะมา! มาเล่นปาสโนว์บอลกับมนุษย์หิมะกันเถอะ! ร่วมทีมเพื่อทำภารกิจท้าทายมนุษย์หิมะ และรวบรวมวัสดุเพื่ออัพเกรดสกิลโรงงานมนุษย์หิมะ คุณจะได้รับรางวัล เช่น สโนว์บอล อวตารคริสต์มาส กรอบรูปอวตารคริสต์มาส และของที่ระลึกคริสต์มาส!\n\n3. สนับสนุนคริสต์มาส: \nในช่วงกิจกรรม แพ็กเกจที่ซื้อด้วยเหรียญแพ็กเกจ หรือผ่านการเติมเงิน - \"เหมาะสำหรับผู้เล่นใหม่\", \"ยอดฮิต\", \"จำกัดเวลา\", \"กองทุนเพาะปลูก\" จะเพิ่มยอดสะสมใน สถานีชดเชย ของเซิร์ฟเวอร์ เมื่อยอดสะสมขยับขึ้น ก็จะได้รับรางวัลส่วนลด!",
        minipack = 0,
    },
    [2130516] = {
        id = 2130516,
        text = "1. มีการรีเฟรชด่าน 3 ด่านให้อัตโนมัติแก่ผู้เล่นแต่ละคน ในเวลา 00.00 น. ของทุกวัน แตะที่ไอคอน ด่าน เพื่อสร้างห้อง เมื่อเคลียร์ด่านแล้ว คุณจะท้าทายด่านอีกไม่ได้ \n\n2. คุณสามารถใช้ Diamond เพื่อรีเซ็ตด่านได้ทันที โปรดระวัง: ด่านที่ยังไม่ท้าทายจะถูกรีเซ็ตเช่นกัน คุณมีโอกาสจำกัดในการรีเซ็ตในแต่ละวัน \n\n3. ผู้เล่นสามารถรวมทีมในฮอลเพื่อท้าทายด่านกิจกรรมหรือช่วยเหลือผู้อื่นได้ (ซึ่งจะได้รับรางวัลในด่านเดียวกัน) \n\n4. คุณมีโอกาสช่วยเหลือแบบจำกัดในแต่ละวัน ซึ่งจะรีเซ็ตทุกวัน คุณควรใช้โอกาสของคุณให้หมดภายในแต่ละวัน",
        minipack = 0,
    },
    [2130518] = {
        id = 2130518,
        text = "สงครามหิมะสิ้นสุดลงแล้ว ไอเทมที่คุณยังไม่ได้รับในโต๊ะทำงานมนุษย์หิมะอยู่ที่นี่แล้ว กรุณาตรวจดู \nร้านค้าจะปิดตัวหลังวันที่ 10-1-2020 กรุณาแลกเปลี่ยนให้ทันเวลา",
        minipack = 0,
    },
