    [266680] = {
        id = 266680,
        text = "Get the costume - \"Show Time\" to activate this avatar frame",
        minipack = 0,
    },
    [14300208] = {
        id = 14300208,
        text = "ขีดจำกัดการจัดเก็บ",
        minipack = 0,
    },
    [14300216] = {
        id = 14300216,
        text = "ประวัติย่อของเธอแค่เขียนไว้: \"ต้องการผู้ช่วยเพิ่มเติมหรือไม่?\"\nรายได้จะเพิ่มขึ้นเมื่อได้รับ\"โน้ตดนตรีหลักสูตรการปฏิบัติ,เหรียญดอกไม้ไฟ,สมาชิกผู้เปล่งประกาย,แป้งข้าวเหนียว\"",
        minipack = 0,
    },
    [14300224] = {
        id = 14300224,
        text = "เธอร่วมมือกับคนอื่นไม่เก่งเพราะเธอขี้อาย ดูเหมือนว่าเขาจะร่วมมือกับคนอื่นไม่เก่งเพราะเขากลัวชีวิต\nรายได้จะเพิ่มขึ้นเมื่อได้รับ\"เหรียญนำโชคตรุษจีน,กระดาษสีแดง,แป้งข้าวเหนียว\"",
        minipack = 0,
    },
    [266681] = {
        id = 266681,
        text = "Snow Melt",
        minipack = 0,
    },
    [14300240] = {
        id = 14300240,
        text = "นัตสึมิถูกเลือกให้เข้าร่วมการแสดงมายากลบนท้องถนนและได้รับของขวัญพิเศษ",
        minipack = 0,
    },
    [14300248] = {
        id = 14300248,
        text = "โน้ตดนตรีที่ได้บันทึกการฝึกฝนทางโซเชี่ยลที่ใช้ได้จริง ใช้เพื่ออัพเกรดเลเวลตัวละครในกิจกรรม\"การปฏิบัติปีใหม่\" เพื่อเพิ่มยอดขายของคุณ",
        minipack = 0,
    },
    [14300256] = {
        id = 14300256,
        text = "หลักสูตรการปฏิบัติมาพร้อมกับความสุขในฤดูใบไม้ผลิใหม่! สปิริตจำเป็นต้องสำเร็จหลักสูตรการปฏิบัติโซเชี่ยลภายในหนึ่งเดือนเพื่อรับรางวัลตามผลงาน\n\n1. ในหลักสูตรการปฏิบัติ คุณสามารถส่งสปิริตดำเนินการหลักสูตรการปฏิบัติใดก็ได้ โดยแต่ละคลาสจะได้รับรางวัลแตกต่างกัน\n\n2. สปิริตแต่ละตัวจะมีหลักสูตรการปฏิบัติของตนเอง และรายได้ที่ได้รับจากหลักสูตรการปฏิบัติที่เกี่ยวข้องจะเพิ่มขึ้น 4%\n\n3. สามารถอัพเลเวลของสปิริตที่อยู่ในหลักสูตรการปฏิบัติได้ หลังจากนั้นเธอจะได้รับรางวัลเพิ่มขึ้นจากหลักสูตร\n\n4. ในหลักสูตรการปฏิบัติ สปิริตอาจทำให้เกิดอีเว้นท์พิเศษและได้รับรางวัลพิเศษ แต่สปิริตแต่ละตัวสามารถเผชิญกับอีเว้นท์พิเศษได้เพียงหนึ่งครั้งต่อวัน\n\n5. ตามความก้าวหน้าของเวลา รางวัลของหลักสูตรบางวิชาจะเปลี่ยนไป: \n\n2021.2.5-2021.3.13ก.พ.: Gold,โน้ตดนตรีหลักสูตร,เหรียญนำโชคตรุษจีน\n\n2021.2.14-2021.3.1: เหรียญดอกไม้ไฟ,สมาชิกผู้เปล่งประกาย,กระดาษสีแดง\n\n2021.3.1 - สิ้นสุดกิจกรรม: เหรียญเทศกาลโคมไฟ,น้ำตาลทราย,แป้งข้าวเหนียว\n\n6. ผลผลิตของการปฏิบัติแต่ละอีเวนท์มีขีดจำกัด ผลผลิตของสปิริตในอีเวนท์จะถูกเก็บไว้ชั่วคราว และจำเป็นต้องรับด้วยตนเอง หลังจากผลผลิตถึงขีดจำกัดแล้ว สปิริตจะไม่ผลิตไอเทมอีกต่อไป อย่าลืมรับรางวัลทุกวันนะ~\n\n7. ผลผลิตสุดท้ายคือจำนวนพื้นฐาน x (โบนัสระดับสปิริต+ โบนัสอีเวนท์ + โบนัสผู้เชี่ยวชาญสปิริต) คำนวณโดยการปัดเศษ\n\n8. ในหลักสูตรการปฏิบัติจะมีหลักสูตรที่แตกต่างกันสองวิชาที่ได้รับกำไรเพิ่มขึ้นทุกวัน และผลผลิตของกิจกรรมจะเพิ่มขึ้นอีก 10% ในสถานะบัฟ อีเว้นท์บัฟจะเปลี่ยนในทุกวันเวลา 12:30 น.",
        minipack = 0,
    },
