    [14210162] = {
        id = 14210162,
        text = "เรียนผู้ทำสัญญา\nราทาโทสได้ตรวจพบความผันผวนอย่างรุนแรงของพลังสปิริตอีกครั้ง วิเคราะห์ได้พบว่า พารามิเตอร์ของสปิริตมีความสอดคล้องอย่างยิ่งกับมายูริ!\nการแจ้งเตือนสำคัญ! ทุกคนในราทาโทส เตรียมตัวให้พร้อมสำหรับศัตรูที่แข็งแกร่ง\nคุณมายูริกลับมาแล้วใช่มั้ย?\nนักออกแบบที่ไร้นาม D·A·L",
        minipack = 0,
    },
