    [15058] = {
        id = 15058,
        text = "AST พัฒนาระบบไฟฟ้านี้กับรัฐบาลญี่ปุ่น ใช้เพื่อทะลุสปิริต",
        minipack = 0,
    },
    [190000439] = {
        id = 190000439,
        text = "รางวัลจะปลดล็อคเมื่อคะแนนรวมของสมาชิกทั้งหมดในคลับปัจจุบันของผู้เล่นถึงจำนวนที่กำหนดแล้ว โปรดเช็คดูรายละเอียดเพิ่มเติมที่อินเทอร์เฟซการแสดงรางวัล! หากผู้เล่นเปลี่ยนคลับในช่วงเวลากิจกรรม คะแนนที่ได้รับก่อนการเปลี่ยนแปลงจะถูกคำนวณในคลับเดิมและคะแนนที่ได้รับหลังจากการเปลี่ยนแปลงจะถูกคำนวณในคลับปัจจุบัน และรางวัลจะแจกตามผลคลับปัจจุบันของผู้เล่น",
        minipack = 0,
    },
    [10503003] = {
        id = 10503003,
        text = "ถล่มศัตรูที่อยู่ด้านหน้าด้วยลำแสงเปลวเพลิงของภูติเผาทำลาย: ปืนใหญ่\nสร้าง DMG เปลวไฟเท่ากับ 1000% ATK\nภูติเผาทำลาย: รูปแบบปืนใหญ่ต้นทุน 4 ความโกรธทุกวินาที เมื่อความโกรธลดลงเหลือ 0 ให้เปลี่ยนกลับเป็นรูปแบบขวานโบราณ",
        minipack = 0,
    },
    [10503011] = {
        id = 10503011,
        text = "[ภูติเผาทำลาย] อัตราทะลวง +6%",
        minipack = 0,
    },
    [10503019] = {
        id = 10503019,
        text = "[ภูติเผาทำลาย] สร้าง DMG ให้ศัตรูที่เป็นมนุษย์ +6%",
        minipack = 0,
    },
    [10503027] = {
        id = 10503027,
        text = "[ภูติเผาทำลาย] มีโอกาส 12% ที่จะทำให้เป้าหมายจุดไฟในขณะโจมตี\n[เป้าหมายที่ถูกจุดไฟจะได้รับ DMG เท่ากับ 10% ของ ATK ของโคโทริในทุกๆวินาที ต่อเนื่อง 8 วินาที ซ้อนกันได้สูงสุด 10 ชั้น หลังจากถึงชั้นสูงสุด โคโทริจะจุดระเบิดเปลวไฟแก่เป้าหมายเพิ่มเติม 1 ครั้ง สร้าง DMG เท่ากับ 30% ของ ATK ของโคโทริในบริเวณเล็ก ๆ ดาเมจจากการระเบิดจะคำนวณค่า DEF ของเป้าหมายใหม่อีกครั้ง]",
        minipack = 0,
    },
    [10503035] = {
        id = 10503035,
        text = "[ภูติเผาทำลาย] โอกาสที่จะทำให้เป้าหมายจุดไฟในขณะโจมตี +8%\n[เป้าหมายที่ถูกจุดไฟจะได้รับ DMG เท่ากับ 10% ของ ATK ของโคโทริในทุกๆวินาที ต่อเนื่อง 8 วินาที ซ้อนกันได้สูงสุด 10 ชั้น หลังจากถึงชั้นสูงสุด โคโทริจะจุดระเบิดเปลวไฟแก่เป้าหมายเพิ่มเติม 1 ครั้ง สร้าง DMG เท่ากับ 30% ของ ATK ของโคโทริในบริเวณเล็ก ๆ ดาเมจจากการระเบิดจะคำนวณค่า DEF ของเป้าหมายใหม่อีกครั้ง]",
