    [3203202] = {
        id = 3203202,
        text = "2. แต่ละขั้นจะมีขั้นย่อย 3 ขั้น เมื่อคะแนนการต่อสู้เพิ่มขึ้น คุณจะได้ขึ้น/ลงขั้น หรืออยู่ในขั้นเดิม",
        minipack = 0,
    },
    [3203204] = {
        id = 3203204,
        text = "4. คุณจะได้รับ \"คะแนนต่อสู้\" และจัดอันดับแรงค์หลังท้าทายด่านในโซนต่อสู้ แรงค์ที่สูงขึ้นจะได้รับคะแนนมากขึ้น และคุณจะเสียคะแนนเมื่อมีแรงค์รั้งท้าย",
        minipack = 0,
    },
    [3203206] = {
        id = 3203206,
        text = "6. ในการแข่ง [ขั้นบันได] คะแนนต่ำสุดที่คุณจะมีคือ 0 และจะไม่มีการติดลบ (หากคะแนนต่อสู้ของคุณคือ 0 คุณจะไม่ได้รับคะแนนไม่ว่าจะอยู่ขั้นไหน)",
        minipack = 0,
    },
    [3203208] = {
        id = 3203208,
        text = "8. ในแต่ละรอบ เซฟิร่าและของที่ระลึก ที่ติดตัวสปิริต จะถูกผูกไว้กับพวกมัน ซึ่งหมายความว่าสปิริตอื่นๆ จะไม่สามารถใช้มันได้ (สามารถใช้พวกนั้นใน กระเป๋าได้แล้ว)",
        minipack = 0,
    },
    [3203210] = {
        id = 3203210,
        text = "10. การ์ดต่อสู้จะรับได้จากการสำเร็จภารกิจต่อสู้หรือรางวัลคำนวณของรอบ การ์ดสามารถอัพเกรดเป็นเลเวลที่สูงขึ้นได้",
        minipack = 0,
    },
    [3203212] = {
        id = 3203212,
        text = "1. แต่ละโซนจะแบ่งออกเป็นหลายชั้น ในแต่ละชั้นจะแบ่งออกเป็นหลายด่าน",
        minipack = 0,
    },
    [3203214] = {
        id = 3203214,
        text = "3. แต่ละชั้นจะมี Boss ด่าน 1 ตน ถ้าหากคุณท้าทาย Boss ก่อนที่จะผ่านด่านทั่วไป Boss จะได้รับคุณสมบัติพิเศษ",
        minipack = 0,
    },
    [3203216] = {
        id = 3203216,
        text = "5. มีเพียง Boss ด่านในชั้นสุดท้ายเท่านั้นที่จะมีคะแนนเวลาและสามารถท้าทายซ้ำได้ ในด่านอื่นๆ จะมีเพียงคะแนนผ่านด่านเท่านั้น",
        minipack = 0,
    },
    [3203218] = {
        id = 3203218,
        text = "7. ในแต่ละรอบ สปิริตจะมีโอกาสในการท้าทายด่าน 3 ครั้ง (ไม่ว่าผลจะแพ้หรือชนะก็ตาม) เมื่อใช้โอกาสหมดแล้ว คุณจะต้องรอจนกว่าจะถึงรอบถัดไปถึงจะใช้งานพวกเขาได้",
        minipack = 0,
    },
    [3203220] = {
        id = 3203220,
        text = "1. การ์ดต่อสู้สามารถแบ่งออกได้เป็น 4 ขั้น: ทั่วไป, งดงาม, หายาก และล้ำค่า พวกมันจะมีเอฟเฟกต์กระทำหรือถูกกระทำ",
        minipack = 0,
    },
    [3203222] = {
        id = 3203222,
        text = "3. การ์ดที่มีเอฟเฟกต์ถูกกระทำจะได้รับเอฟเฟกต์โดยตรงในด่าน",
        minipack = 0,
    },
    [3203224] = {
        id = 3203224,
        text = "5. การ์ดแต่ละใบสามารถอัพเกรดได้ถึง Lv.10 ด้วยการ์ดที่เหมือนกัน เมื่อมีการ์ดที่ซ้ำกันถึง Lv.10 แล้วมันจะเปลี่ยนเป็นเพชรพลอยชาร์มอัตโนมัติ",
        minipack = 0,
    },
