    [14210163] = {
        id = 14210163,
        text = "เรียนพันธสัญญาที่รัก\nราทาโทสพบว่าค่าอารมณ์ของโทบิอิจิ โอริกามิ กำลังลดดิ่งลงโดยไม่ทราบสาเหตุ และขณะนี้สถานการณ์ในที่เกิดเหตุนั้นกำลังเข้าสู่ขั้นวิกฤต สถานการณ์ฉุกเฉิน! โปรดเตรียมพร้อมออกไปสำรวจ และอย่าลืมใส่ใจปกป้องความปลอดภัยของคุณ\nHot Games ทำงานอย่างหนักเพื่อที่จะทำให้โอริกามิออกมาดูดี",
        minipack = 0,
    },
    [14210161] = {
        id = 14210161,
        text = "เรียนผู้ทำสัญญา\nขอบคุณเทคโนโลยีล่าสุดจากนัตสึมิ การสนทนา AI ของโทวกะ - \"โทซากะ\" ได้เข้าร่วมราทาโทสอย่างเป็นทางการ\nเราจะพยายามอย่างเต็มที่เพื่อที่จะปรับปรุงเกมและเพิ่มเนื้อหาให้ดียิ่งขึ้นสำหรับทุกคน ต่อไปจะมีสปิริตใหม่เพิ่มเข้ามาในแชทประจำวัน โปรดคอยติดตาม!\n Hot Games",
        minipack = 0,
    },
    [270454] = {
