    [13312009] = {
        id = 13312009,
        text = "A badge with power beyond comprehension, earned in the depth of the deadly Planar World. Collect them to gain personal and Club Support Points (must be in the club for at least 24 hours).",
        minipack = 0,
    },
    [13400201] = {
        id = 13400201,
        text = "เด็กผู้หญิงหน้าตาน่ารักจากโรงเรียนมัธยมใกล้ ๆ เธอมาทำงานเป็นพาร์ทไทม์ แม้ว่าจะไม่เคยมีประสบการณ์ก่อน แต่เธอก็ทำงานหนักและเรียนรู้ได้เร็ว",
        minipack = 0,
    },
    [13400200] = {
        id = 13400200,
        text = "เมดสาวที่โดดเด่นด้วยผมสีน้ำเงินของเธอ และนั่นทำให้เธอเป็นที่นิยมในหมู่ลูกค้าอีกด้วย เธอมักจะถอนหายใจโดยไม่รู้ตัว",
        minipack = 0,
    },
    [13400199] = {
        id = 13400199,
        text = "สาวใช้น่ารักที่ไม่ค่อยแสดงตัวให้ลูกค้าเห็น การแสดงมายากลประจำวันของเธอในเวลา 20:00 น. ถือเป็นจุดเด่นของร้านกาแฟแห่งนี้",
        minipack = 0,
    },
    [13400198] = {
        id = 13400198,
        text = "เธอไม่เคยคุยกับลูกค้าแปลกหน้า และเมื่อเธอยืนนิ่งเธอก็คล้ายกับตุ๊กตาเซรามิก",
        minipack = 0,
    },
    [13400197] = {
        id = 13400197,
        text = "เธอไม่รู้อะไรเกี่ยวกับหน้าที่ของเธอ แต่เพราะความน่ารักของเธอ เลยทำให้เธอยังคงเป็นที่นิยมในหมู่ลูกค้าเสมอ",
        minipack = 0,
    },
    [13400196] = {
        id = 13400196,
        text = "เมดสาวไอดอลที่รู้จักกันดีในเรื่องน้ำเสียงที่ไพเราะรวมกับเทวทูต และเธอเกลียดชังลูกค้าผู้ชายอย่างมาก",
        minipack = 0,
    },
    [13400195] = {
        id = 13400195,
        text = "หญิงสาวที่ขยันขันแข็ง เก่งในการเปลี่ยนส่วนผสมทุกประเภทให้เป็นหม้อตุ๋นที่น่ากลัว",
        minipack = 0,
    },
    [13400194] = {
        id = 13400194,
        text = "เมดสาวที่ทำงานอย่างพิถีพิถัน เธอหวังที่จะรักษาทุกอย่างให้เป็นระเบียบ แต่นั่นก็เป็นเพียงความหวัง...",
        minipack = 0,
    },
    [13400193] = {
        id = 13400193,
        text = "เมดระดับผู้จัดการร้านกาแฟ ที่ทำหน้าที่จัดงานให้กับเมดคนอื่น ๆ และจัดการทำงานทุกอย่างอย่างแท้จริง แต่บางครั้งเธอก็ทำตัวน่ารักเช่นกัน",
        minipack = 0,
    },
    [13400192] = {
        id = 13400192,
        text = "เมดสาวที่มีออร่าสังหารแผ่อยู่รอบกาย แม้ว่าเธอจะสวยงามมาก แต่อย่าเผลอเข้าใกล้เชียวล่ะ เพราะอาจเป็นอันตรายได้",
        minipack = 0,
    },
    [13400191] = {
        id = 13400191,
        text = "เมดที่ถูกขนานนามว่า \"กูรูการหาคู่\" และด้วยบุคลิกภาพเชิงรุกของเธอ มักจะทำให้คนอื่นไปไม่เป็นอยู่เสมอ",
        minipack = 0,
    },
    [13400190] = {
        id = 13400190,
        text = "เมดที่ได้รับความนิยมมากที่สุดในร้านกาแฟ แม้ว่ามักจะสร้างปัญหาอยู่เสมอ แต่ลูกค้าก็ล้วนให้อภัยเสมอ เพราะเธอดันทำตัวน่ารักเกินไป",
        minipack = 0,
    },
    [13400189] = {
        id = 13400189,
        text = "เมดสาวผมบลอนด์ที่ดูดุดัน แต่อาจจะโก๊ะบ้างเมื่อถูกลูกค้าดุ",
        minipack = 0,
    },
    [13400188] = {
        id = 13400188,
        text = "เมดสาวน่ารักใส่แว่น ที่มักจะเยาะเย้ยคนอื่น แต่ถ้าคุณกล้ายั่วโมโหเธอ เธอก็จะแกล้งคุณคืนจากทางด้านหลัง",
        minipack = 0,
    },
    [13400187] = {
        id = 13400187,
        text = "เมดสาวผมสั้นที่ดูไร้เดียงสา อย่าสนใจคำพูดตัดบทของเธอมากนัก",
        minipack = 0,
    },
    [13400186] = {
        id = 13400186,
        text = "เมดผมหางม้า เธอเก่งในการนวด บางครั้งความตรงไปตรงมาของเธอก็มักจะทำให้ลูกค้าอับอาย",
        minipack = 0,
    },
    [13400185] = {
        id = 13400185,
        text = "เมดที่มีใบหน้าอ่อนล้า แม้จะเหม่อลอยในการทำสิ่งต่างๆ แต่ท่าทีสุภาพของเธอก็ช่วยให้เธอไม่โดนแขกบ่น",
        minipack = 0,
    },
    [13400184] = {
